-- Generated by scripts/generate-pedia-curation.mjs from the reviewed 2026-10-15 release.
-- No network/order/secret access. Current mirrored rates determine prices.
-- Preserve all existing order IDs, mappings, and terms before changing the catalog.

UPDATE pedia_order_items SET snapshot_json=json_set(
    CASE WHEN json_valid(snapshot_json) AND json_type(snapshot_json)='object' THEN snapshot_json ELSE '{}' END,
    '$.refill_days', COALESCE(CASE WHEN json_valid(snapshot_json) THEN json_extract(snapshot_json,'$.refill_days') END,(SELECT refill_days FROM pedia_tiers WHERE id=pedia_order_items.tier_id),0),
    '$.service_copy', json(COALESCE(CASE WHEN json_valid(snapshot_json) THEN json_extract(snapshot_json,'$.service_copy') END,(SELECT json_object('product_name',substr(p.name,1,120),'service_name',substr(COALESCE(t.public_name,t.label_note,p.name),1,200),'description',substr(COALESCE(t.description_md,''),1,3000),'terms',substr(COALESCE(t.terms_md,''),1,3000),'instructions',substr(COALESCE(t.instructions_md,''),1,3000)) FROM pedia_products p JOIN pedia_tiers t ON t.product_id=p.id WHERE t.id=pedia_order_items.tier_id))),
    '$.min_profit_rp', COALESCE(CASE WHEN json_valid(snapshot_json) THEN json_extract(snapshot_json,'$.min_profit_rp') END,(SELECT min_profit_rp FROM pedia_tiers WHERE id=pedia_order_items.tier_id),0)
  );

CREATE TABLE pedia_release_products_20261015(slug TEXT PRIMARY KEY,platform TEXT,metric TEXT,target_kind TEXT,name TEXT,description_md TEXT,checklist_json TEXT,packages_json TEXT,sort_order INTEGER);

CREATE TABLE pedia_release_services_20261015(product_slug TEXT,supplier TEXT,service_id INTEGER,public_name TEXT,description_md TEXT,terms_md TEXT,instructions_md TEXT,recommendation_note TEXT,region TEXT,quality TEXT,refill_days INTEGER,eta_start TEXT,speed_note TEXT,drop_risk TEXT,min_qty_override INTEGER,max_qty_override INTEGER,quantity_step INTEGER,sort_order INTEGER,is_recommended INTEGER,target_format TEXT,refill_anchor TEXT,PRIMARY KEY(product_slug,supplier,service_id));

