INSERT INTO pedia_products(slug,platform,metric,target_kind,name,description_md,checklist_json,packages_json,step,sort_order,is_active,is_featured)
  SELECT slug,platform,metric,target_kind,name,description_md,checklist_json,packages_json,1,sort_order,0,0 FROM pedia_release_products_20261015 WHERE 1
  ON CONFLICT(slug) DO UPDATE SET platform=excluded.platform,metric=excluded.metric,target_kind=excluded.target_kind,name=excluded.name,
    description_md=excluded.description_md,checklist_json=excluded.checklist_json,packages_json=excluded.packages_json,step=1,sort_order=excluded.sort_order,updated_at=datetime('now');

UPDATE pedia_tiers SET is_active=0 WHERE product_id IN (SELECT p.id FROM pedia_products p JOIN pedia_release_products_20261015 c ON c.slug=p.slug);

INSERT INTO pedia_tiers(product_id,tier,label_note,supplier,supplier_service_id,backup_service_id,price_group,markup_pct,min_profit_rp,refill_days,eta_start,eta_finish,package_prices_json,is_active,public_name,description_md,terms_md,instructions_md,recommendation_note,region,quality,speed_note,drop_risk,is_recommended,sort_order,min_qty_override,max_qty_override,quantity_step,target_format,refill_anchor)
  SELECT p.id,'standar',c.public_name,c.supplier,c.service_id,NULL,'G3',20,1000,c.refill_days,c.eta_start,NULL,'{}',1,
    c.public_name,c.description_md,c.terms_md,c.instructions_md,c.recommendation_note,c.region,c.quality,c.speed_note,c.drop_risk,c.is_recommended,c.sort_order,c.min_qty_override,c.max_qty_override,c.quantity_step,c.target_format,c.refill_anchor
  FROM pedia_release_services_20261015 c JOIN pedia_products p ON p.slug=c.product_slug
  JOIN pedia_supplier_services s ON s.supplier=c.supplier AND s.service_id=c.service_id
  WHERE s.present=1 AND s.type='Default' AND s.rate_idr_per_1k>0
    AND MAX(s.min_qty,c.min_qty_override)>0 AND MIN(s.max_qty,c.max_qty_override)>=MAX(s.min_qty,c.min_qty_override)
  ON CONFLICT(product_id,supplier,supplier_service_id) DO UPDATE SET label_note=excluded.label_note,backup_service_id=NULL,
    refill_days=excluded.refill_days,eta_start=excluded.eta_start,eta_finish=NULL,public_name=excluded.public_name,
    description_md=excluded.description_md,terms_md=excluded.terms_md,instructions_md=excluded.instructions_md,
    recommendation_note=excluded.recommendation_note,region=excluded.region,quality=excluded.quality,speed_note=excluded.speed_note,
    drop_risk=excluded.drop_risk,is_recommended=excluded.is_recommended,sort_order=excluded.sort_order,
    min_qty_override=excluded.min_qty_override,max_qty_override=excluded.max_qty_override,quantity_step=excluded.quantity_step,target_format=excluded.target_format,refill_anchor=excluded.refill_anchor,
    is_active=1,auto_disabled_reason=NULL,updated_at=datetime('now');

WITH quantities AS (
  SELECT t.id,CAST(j.value AS INTEGER) AS qty,s.rate_idr_per_1k AS rate,t.markup_pct AS markup,t.min_profit_rp AS min_profit
  FROM pedia_tiers t JOIN pedia_products p ON p.id=t.product_id
  JOIN pedia_release_services_20261015 c ON c.product_slug=p.slug AND c.supplier=t.supplier AND c.service_id=t.supplier_service_id
  JOIN pedia_supplier_services s ON s.supplier=t.supplier AND s.service_id=t.supplier_service_id
  JOIN json_each(p.packages_json) j
  WHERE t.is_active=1 AND s.present=1 AND s.type='Default' AND s.rate_idr_per_1k>0
    AND CAST(j.value AS INTEGER) BETWEEN MAX(s.min_qty,t.min_qty_override) AND MIN(s.max_qty,t.max_qty_override)
    AND CAST(j.value AS INTEGER)%t.quantity_step=0
), raw AS (
  SELECT id,qty,MAX(qty*rate/1000.0*(1+markup/100.0),qty*rate/1000.0+min_profit) AS amount FROM quantities
), stepped AS (
  SELECT id,qty,amount,CASE WHEN amount<10000 THEN 100 ELSE 500 END AS step FROM raw
), prices AS (
  SELECT id,qty,MAX(1000,CAST(amount/step AS INTEGER)*step+CASE WHEN amount>CAST(amount/step AS INTEGER)*step THEN step ELSE 0 END) AS price FROM stepped
)
UPDATE pedia_tiers SET package_prices_json=COALESCE((SELECT json_group_object(CAST(qty AS TEXT),price) FROM prices WHERE prices.id=pedia_tiers.id),'{}'),
  rate_snapshot=(SELECT rate_idr_per_1k FROM pedia_supplier_services s WHERE s.supplier=pedia_tiers.supplier AND s.service_id=pedia_tiers.supplier_service_id),updated_at=datetime('now')
WHERE EXISTS(SELECT 1 FROM pedia_products p JOIN pedia_release_services_20261015 c ON c.product_slug=p.slug WHERE p.id=pedia_tiers.product_id AND c.supplier=pedia_tiers.supplier AND c.service_id=pedia_tiers.supplier_service_id);

UPDATE pedia_tiers SET is_active=0,auto_disabled_reason='service_missing' WHERE is_active=1 AND package_prices_json='{}' AND product_id IN (SELECT p.id FROM pedia_products p JOIN pedia_release_products_20261015 c ON c.slug=p.slug);

UPDATE pedia_products SET is_active=CASE WHEN EXISTS(SELECT 1 FROM pedia_tiers t WHERE t.product_id=pedia_products.id AND t.is_active=1 AND t.package_prices_json<>'{}') THEN 1 ELSE 0 END,updated_at=datetime('now') WHERE slug IN (SELECT slug FROM pedia_release_products_20261015);

DROP TABLE pedia_release_services_20261015;
DROP TABLE pedia_release_products_20261015;
